{
  "vulnerable_symbols": [
    "axios",
    "axios.request"
  ],
  "trigger": "在浏览器中，axios 请求的 withXSRFToken 被原型污染或误配置为 truthy 非布尔值时，跨域请求会绕过同源检查并携带 XSRF token。",
  "preconditions": [
    "运行在浏览器环境（hasStandardBrowserEnv 为 true）",
    "config.withXSRFToken 被设置为 truthy 非布尔值（如通过原型污染或错误配置）",
    "应用会向跨域/不同源目标发起请求，且浏览器中存在可被 Axios 读取的 XSRF token"
  ],
  "exploit_evidence": [
    {
      "src": 2,
      "kind": "poc",
      "quote": "⚠️ Exploit Status: POC"
    }
  ],
  "fixed_version": "1.15.1 / 0.31.1",
  "summary_zh": "Axios 的 withXSRFToken 被污染为真值后，跨域请求会泄漏 XSRF token，应升级修复。"
}
